WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_basic_logic'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '逻辑思维框架', 'kp-ms-basic-logic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "逻辑思维框架"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "观点先行，总分总结构。不列点，绝对不开口。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、为什么必须要列点？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "考官一天要听几十号人答题，耳朵是会疲劳的。如果你说了一长串散文，考官根本抓不到你的得分点。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "必须使用极度生硬的连接词：“针对这个问题，我有以下三点看法。第一... 第二... 第三...”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题的“洋葱模型”"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[表层: 亮明观点 (一句话定调)] --> B[中层: 分析原因/影响/合理性]\nB --> C[里层: 提出具体可行的对策/建议]\nC --> D[底层: 升华总结 (拔高立意)]"}}]}$$ AS jsonb), NULL, '逻辑思维框架的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "基础素养", "逻辑思维"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_basic_logic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
